  if (first) return { mode: first[1].toLowerCase(), prompt: first[2].trim() };
  const last = body.match(new RegExp(`^([\\s\\S]*?)\\s*\\[(${COMMENT_TAGS})\\]\\s*$`, 'i'));
  if (last) return { mode: last[2].toLowerCase(), prompt: last[1].trim() };
  return null;
}

